const fs = require('fs');
const src = fs.readFileSync('._sim_check.js', 'utf8');

const gradient = { addColorStop: () => {} };
const ctxStub = new Proxy({}, {
  get: (t, prop) => {
    if (prop === 'createLinearGradient') return () => gradient;
    return function () {};
  },
  set: () => true
});
const elements = {};
function el(id) {
  if (!elements[id]) {
    elements[id] = {
      id, textContent: '', innerHTML: '', style: {},
      clientWidth: 1000, clientHeight: 600,
      addEventListener: () => {},
      getContext: () => ctxStub,
      width: 0, height: 0
    };
  }
  return elements[id];
}
global.window = { addEventListener: () => {}, devicePixelRatio: 1 };
global.document = { getElementById: id => el(id) };
global.performance = { now: () => simTime };
let simTime = 0;
let rafCb = null;
global.requestAnimationFrame = cb => { rafCb = cb; };

// expose internals for assertions: re-run src and grab nothing; instead track via DOM stubs
const el_status = elements['statusLine'] || null;

eval(src);

// drive frames manually: call rafCb with increasing time
let frames = 0;
for (let i = 0; i < 4000; i++) {
  const t = i * 16.7;
  simTime = t;
  const cb = rafCb;
  rafCb = null;
  if (!cb) throw new Error('no rAF callback scheduled');
  cb(t);
  frames++;
}
console.log('ran frames:', frames);
console.log('statusLine:', el('statusLine').innerHTML);
console.log('emptyFloor chip:', el('emptyFloor').textContent);
console.log('cabinFloor chip:', el('cabinFloor').textContent);
